function Logo({ h = 44, style }) { return <img src={LOGO_MARK} alt="" draggable={false} style={{ height: h, width: "auto", display: "block", pointerEvents: "none", ...style }} />; }
function Guy({ pose = "wave", h = 160, style }) {
  return <img src={GUY[pose]} alt="" draggable={false} style={{ height: h, width: "auto", display: "block", pointerEvents: "none", maxWidth: "none", ...style }} />;
}

function Face({ ic, w = 96, h = 120, radius = 16, caption = true, big = false }) {
  const src = PHOTOS[ic.wing];
  const foc = (typeof FOCUS !== "undefined" && FOCUS[ic.wing]) || ["50% 40%", 1];
  return (
    <div style={{ position: "relative", width: w, height: h, borderRadius: radius, overflow: "hidden", background: src ? "#000" : `linear-gradient(160deg, ${ic.tint}, ${C.ink})`, flexShrink: 0 }}>
      {src && <img src={src} alt="" style={{ width: "100%", height: "100%", objectFit: "cover", objectPosition: big ? foc[0] : "50% 30%" }} />}
      {!src && <div style={{ position: "absolute", inset: 0, display: "flex", alignItems: "center", justifyContent: "center", fontFamily: F.serif, fontSize: big ? 64 : 36, color: "#ffffff33" }}>{ic.short[0]}</div>}
      {caption && <><div style={{ position: "absolute", inset: 0, background: "linear-gradient(180deg, transparent 50%, #161310dd 100%)" }} /><div style={{ position: "absolute", left: 12, right: 12, bottom: 12 }}><div style={{ fontFamily: F.serif, fontSize: big ? 22 : 15, color: "#fff", lineHeight: 1.05 }}>{ic.name}</div><div style={{ ...eyebrow, color: C.gold, fontSize: 8, marginTop: 4 }}>{label(ic.wing)} · reads their own faith</div></div></>}
    </div>
  );
}
function Btn({ children, onClick, kind = "ink", disabled }) {
  const st = { ink: { background: C.ink, color: C.gold }, gold: { background: C.gold, color: C.ink }, ghost: { background: "transparent", color: C.ink, border: `1.5px solid ${C.ink}` }, light: { background: "#fff", color: C.ink } }[kind];
  return <div onClick={disabled ? undefined : onClick} style={{ ...st, ...(disabled ? { background: C.line, color: C.mute, border: "none" } : {}), textAlign: "center", borderRadius: 999, padding: "15px 18px", fontFamily: F.sans, fontWeight: 600, fontSize: 13, letterSpacing: "0.06em", textTransform: "uppercase", cursor: disabled ? "default" : "pointer" }}>{children}</div>;
}
function Card({ children, style, dark, onClick }) {
  return <div onClick={onClick} style={{ background: dark ? C.ink : "#fff", color: dark ? C.cream : C.ink, border: dark ? "none" : `1px solid ${C.line}`, borderRadius: 20, padding: 16, boxShadow: "0 8px 30px rgba(22,19,16,.05)", cursor: onClick ? "pointer" : "default", ...style }}>{children}</div>;
}
function Opt({ on, onClick, children, sub }) {
  return <div onClick={onClick} style={{ border: `1.5px solid ${on ? C.ink : C.line}`, background: on ? "#FFFBE0" : "#fff", borderRadius: 16, padding: "13px 16px", cursor: "pointer" }}><div style={{ fontFamily: F.sans, fontWeight: 600, fontSize: 14, color: C.ink }}>{children}</div>{sub && <div style={{ ...body, fontSize: 12, marginTop: 3, color: C.mute }}>{sub}</div>}</div>;
}
function Bubble({ children }) {
  return <div style={{ position: "relative", background: "#fff", border: `1px solid ${C.line}`, borderRadius: 18, padding: "14px 16px", fontFamily: F.serif, fontSize: 18, lineHeight: 1.25, color: C.ink, flex: 1 }}>{children}</div>;
}


