// ─── Art-directed imagery: Scene (dusk over water, figures sitting) and ImageBand (photo slot with a brief) ─
function Scene({ h = 400 }) {
  return (
    <svg viewBox="0 0 400 400" preserveAspectRatio="xMidYMid slice" style={{ position: "absolute", inset: 0, width: "100%", height: "100%" }}>
      <defs>
        <linearGradient id="sky" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#111111" /><stop offset="0.45" stopColor="#1c1c1c" /><stop offset="0.72" stopColor="#8C8A3E" /><stop offset="0.9" stopColor="#F5C400" /></linearGradient>
        <linearGradient id="water" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#F5C400" stopOpacity="0.9" /><stop offset="1" stopColor="#111111" /></linearGradient>
        <radialGradient id="glow" cx="0.5" cy="0.5" r="0.5"><stop offset="0" stopColor="#FFF3C4" /><stop offset="0.5" stopColor="#FFE066" stopOpacity="0.9" /><stop offset="1" stopColor="#FFE066" stopOpacity="0" /></radialGradient>
      </defs>
      <rect width="400" height="400" fill="url(#sky)" />
      <circle cx="200" cy="262" r="120" fill="url(#glow)" opacity="0.55" />
      <circle cx="200" cy="262" r="34" fill="#FFF3C4" />
      <path d="M0 250 Q 60 215 120 232 T 240 226 T 400 238 L400 290 L0 290 Z" fill="#111111" opacity="0.85" />
      <path d="M0 268 Q 90 240 170 258 T 400 262 L400 300 L0 300 Z" fill="#0B2A21" />
      <rect y="290" width="400" height="110" fill="url(#water)" />
      <path d="M150 300 Q200 296 250 300 L246 330 Q200 324 154 330 Z" fill="#FFF3C4" opacity="0.25" />
      {[[70, 300, 1.0], [118, 306, 1.15], [172, 302, 1.3], [232, 304, 1.25], [286, 300, 1.1], [332, 305, 0.95]].map(([x, y, k], i) => (
        <g key={i} transform={`translate(${x} ${y}) scale(${k})`} fill="#111111">
          <ellipse cx="0" cy="-2" rx="16" ry="7" /><rect x="-13" y="-30" width="26" height="30" rx="12" /><circle cx="0" cy="-38" r="8" />
        </g>))}
      <rect y="298" width="400" height="6" fill="#111111" opacity="0.6" />
    </svg>
  );
}
function ImageBand({ brief, src, h = 220, radius = 22, children, dark = true }) {
  return (
    <div style={{ position: "relative", height: h, borderRadius: radius, overflow: "hidden", background: src ? "#000" : `linear-gradient(160deg, ${C.dusk1}, ${C.dusk2} 60%, ${C.dusk3})` }}>
      {src ? <img src={src} alt="" style={{ width: "100%", height: "100%", objectFit: "cover" }} /> : <Scene h={h} />}
      <div style={{ position: "absolute", inset: 0, background: "linear-gradient(180deg, transparent 40%, #111111cc 100%)" }} />
      {children && <div style={{ position: "absolute", left: 16, right: 16, bottom: 14, color: "#fff" }}>{children}</div>}
      {!src && brief && <div style={{ position: "absolute", top: 10, right: 12, ...eyebrow, color: "#FFF8E199", fontSize: 6.5, textAlign: "right", maxWidth: 200 }}>photo · {brief}</div>}
    </div>
  );
}

