// ─── the logged-out page: identical sections to the web, in the web's order ─
const STATS = [["33%", "live longer", "women with a weekly practice lived longer over a 16-year study.", "Harvard · JAMA Internal Medicine · 2016"], ["+11", "points happier", "36% of actively religious adults call themselves very happy, vs 25% of everyone else.", "Pew Research · 2019 · to verify"], ["76%", "less depression", "people who said faith mattered had far less depression over ten years.", "Columbia · JAMA Psychiatry · 2014"], ["47", "trials · less anxiety", "47 clinical trials. less anxiety, depression and pain.", "Johns Hopkins · JAMA Internal Medicine · 2014"]];
function SectionHead({ k, t, sub, dark }) { return <div style={{ padding: "0 20px 14px" }}><div style={{ ...eyebrow, color: dark ? C.gold : C.amber }}>{k}</div><div style={{ ...h1, fontSize: 28, marginTop: 6, color: dark ? "#fff" : C.ink }}>{t}</div>{sub && <div style={{ ...body, marginTop: 8, color: dark ? "#ffffffcc" : "#1a1a1a" }}>{sub}</div>}</div>; }
// ─── welcome: the host flow ───────────────────────────────────────────
const MOMENTS = [["sleep", "can't sleep", ["BUDDHISM", "HINDUISM", "CHRISTIANITY"]], ["sick", "someone I love is sick", ["SIKHISM", "CHRISTIANITY", "JUDAISM"]], ["focus", "can't focus", ["HINDUISM", "BUDDHISM", "ISLAM"]], ["family", "my partner's family", ["JUDAISM", "CATHOLIC", "HINDUISM"]], ["curious", "just curious", ["ISLAM", "SIKHISM", "BUDDHISM"]]];
function Welcome({ referrer, onDone, voiceOn, startDoor, onMoment }) {
  const [moment, setMomentLocal] = useState(null);
  // v75: ORDER maps progress index -> screen id. Landing first, then the door picker, then the questions.
  // v155: door -> voice -> go. The questions (how you heard, why you're here, how much you know, minutes) moved out of the way of the first sit; they come back after Day 1 or live in Me.
  const [door, setDoor] = useState(startDoor || null);
  const [pickMode, setPickMode] = useState(false); // v175: "I know my door" opens the picker; otherwise the moment picks tonight's door
  // v175 · no wrong door: moment → tonight's door (guided, one tap) → voice → go. The picker is one quiet line away, never the gate.
  const ORDER = startDoor ? [0, 3, 4, 8] : pickMode ? [0, 11, 3, 4, 8] : [0, 11, 12, 4, 8];
  const suggested = (MOMENTS.find(([id]) => id === moment) || [])[2] ? (MOMENTS.find(([id]) => id === moment) || [])[2][0] : "HINDUISM";
  const [pos, setPos] = useState(startDoor ? (startDoor === "SPIRITUAL" ? 3 : 2) : 0); // v127: from the web, a door is already picked
  const step = ORDER[pos];
  const [heard, setHeard] = useState(null);
  const [why, setWhy] = useState([]);
  const [know, setKnow] = useState(null);
  const [start, setStart] = useState(null); // v117: 'top' | 'find'
  const [time, setTime] = useState(0);
  const N = ORDER.length;
  const canPlace = (d, k) => !!PLACEMENT[d] && k && !/brand new|never sat/i.test(k);
  const next = () => setPos((p) => { let q = Math.min(p + 1, N - 1); if (ORDER[q] === 9 && !canPlace(door, know)) q = Math.min(q + 1, N - 1); return q; });
  const back = () => setPos((p) => { let q = Math.max(0, p - 1); if (ORDER[q] === 9 && !canPlace(door, know)) q = Math.max(0, q - 1); return q; });
  const ic = icon(door || "SPIRITUAL");
  const refIc = referrer ? ICONS.find((i) => i.short === referrer) : null;
  useEffect(() => { if (step === 8) { const t = setTimeout(() => onDone({ door: door || "SPIRITUAL", know, why, heard, time, find: start === "find" }), 2400); return () => clearTimeout(t); } }, [step]);
  const whyLine = why.includes("understand my own religion") ? "then this is exactly the place. nobody explained it to you in your language. we will." : why.includes("my phone owns me") ? "the only app that wants you off your phone. one lesson, then we let you go." : why.includes("lost someone") ? "every path has words for this. we'll go slow." : why.includes("can't sleep") ? "sleep comes easier to people who put the day down. we'll help." : why.length ? "good. you don't have to believe anything. you just have to show up." : "";
  const Host = ({ children }) => <div style={{ display: "flex", gap: 14, alignItems: "flex-start" }}>{door && pos >= 2 ? <Face ic={ic} w={64} h={64} radius={32} caption={false} /> : <Sun size={56} />}<Bubble>{children}</Bubble></div>;

  return (
    <div style={{ position: "absolute", inset: 0, zIndex: 100, background: C.cream, display: "flex", flexDirection: "column", padding: "16px 18px 18px" }}>
      <div style={{ display: step === 0 ? "none" : "flex", alignItems: "center", gap: 12, position: "relative", zIndex: 2 }}>
        <div onClick={back} style={{ ...eyebrow, cursor: "pointer", opacity: step ? 1 : 0.25, fontSize: 16, color: step === 0 ? "#fff" : C.mute }}>‹</div>
        <div style={{ flex: 1, height: 6, background: C.line, borderRadius: 3 }}><div style={{ width: `${Math.max(5, (pos / (N - 1)) * 100)}%`, height: 6, background: C.gold, borderRadius: 3, transition: "width .4s" }} /></div>
        <div onClick={() => onDone({ door: door || "SPIRITUAL", guest: true })} style={{ ...eyebrow, fontSize: 9, cursor: "pointer", textDecoration: "underline", color: step === 0 ? "#fff" : C.mute }}>skip</div>
      </div>
      <div key={step} style={{ flex: 1, minHeight: 0, overflowY: step === 0 ? "hidden" : "auto", display: "flex", flexDirection: "column", justifyContent: "safe center", gap: 16, paddingBottom: 6, animation: "drop .35s ease-out", position: "relative", margin: step === 0 ? "-16px -18px 0" : 0 }}>
        {step === 0 && (<div style={{ position: "absolute", inset: 0, background: C.cream, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", padding: "0 24px 28px", textAlign: "center" }}>
          <div style={{ flex: 1 }} />
          <Logo h={190} />
          <div style={{ fontFamily: F.mark, fontWeight: 800, fontSize: 56, color: C.ink, marginTop: 14, lineHeight: 1 }}>infinite hill</div>
          <div style={{ ...body, fontSize: 17, color: C.mute, marginTop: 12 }}>making religion cool again.</div>
          <div style={{ flex: 1 }} />
          <div style={{ display: "grid", gap: 10, width: "100%" }}>
            <Btn onClick={next}>Start free</Btn>
            <Btn kind="ghost" onClick={() => onDone({ door: "HINDUISM", guest: true })}>I already have an account</Btn>
          </div>
          <div style={{ ...eyebrow, fontSize: 8, marginTop: 14 }}>free · no sign-up · eight doors</div>
        </div>)}
        {step === 1 && (<><Host>How did you hear about infinite hill?</Host><div style={{ display: "grid", gap: 8 }}>{HEARD.map((h) => <Opt key={h} on={heard === h} onClick={() => setHeard(h)}>{h}</Opt>)}</div></>)}
        {step === 2 && (<><Host>What brought you here? Pick anything that's true.</Host><div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>{WHYS.map((w) => <div key={w} onClick={() => setWhy((s) => s.includes(w) ? s.filter((x) => x !== w) : [...s, w])} style={{ border: `1.5px solid ${why.includes(w) ? C.ink : C.line}`, background: why.includes(w) ? "#FFFBE0" : "#fff", borderRadius: 999, padding: "10px 14px", fontFamily: F.sans, fontWeight: 600, fontSize: 13, cursor: "pointer" }}>{w}</div>)}</div>{whyLine && <div style={{ ...body, fontFamily: F.serif, fontSize: 16, color: "#6b6448" }}>{whyLine}</div>}</>)}
        {step === 3 && (<><Host>Which door is yours? You can change it any time — your days come with you.</Host>
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>{DOORS.map(([l, w, n]) => <div key={w} onClick={() => setDoor(w)} style={{ border: `1.5px solid ${door === w ? C.ink : C.line}`, background: door === w ? "#FFFBE0" : "#fff", borderRadius: 16, padding: "14px 12px", cursor: "pointer" }}><div style={{ fontFamily: F.serif, fontSize: 17 }}>{w === "SPIRITUAL" ? "my own path" : l}</div><div style={{ ...eyebrow, fontSize: 8, marginTop: 4, color: C.mute }}>{w === "SPIRITUAL" ? "no door · a bit of each" : "one word a day"}</div></div>)}</div>
          <div style={{ ...eyebrow, textAlign: "center", fontSize: 8 }}><span style={{ color: C.amber }}>more traditions on the way</span> · yours isn't here yet? tell us which</div></>)}
        {step === 11 && (<><Host>What brought you tonight?</Host>
          <div style={{ display: "grid", gap: 8 }}>{MOMENTS.map(([id, l]) => <div key={id} onClick={() => { setMomentLocal(id); onMoment && onMoment(id); }} style={{ border: `1.5px solid ${moment === id ? C.ink : C.line}`, background: moment === id ? "#FFFBE0" : "#fff", borderRadius: 16, padding: "14px 14px", cursor: "pointer", fontFamily: F.serif, fontSize: 17 }}>{l}</div>)}</div>
          <div style={{ ...eyebrow, textAlign: "center", fontSize: 8, color: C.mute }}>we'll pick tonight's door for it. no wrong door — change any time.</div></>)}
        {step === 12 && (() => { const sw = suggested; const si = icon(sw); const d1 = lessonInfo(sw, 1) || DAY1[sw] || {}; return (<><Host>Tonight, try this. One door, one word, one breath. If it doesn't land, tomorrow's a different door — and your days come with you.</Host>
          <div onClick={() => { setDoor(sw); next(); }} style={{ background: "#fff", border: `2px solid ${C.ink}`, borderRadius: 22, padding: 16, cursor: "pointer", display: "flex", gap: 14, alignItems: "center" }}>
            <Face ic={si} w={84} h={84} radius={18} caption={false} />
            <div style={{ flex: 1, minWidth: 0 }}><div style={{ ...eyebrow, fontSize: 8, color: C.mute }}>tonight · {label(sw)} · day 1</div><div style={{ fontFamily: F.serif, fontWeight: 800, fontSize: 24, marginTop: 4, lineHeight: 1.05 }}>{d1.word || "one word"}</div><div style={{ ...body, fontSize: 13, color: C.mute, marginTop: 4 }}>{d1.title || "the oldest hello"} · read by {si.short}</div></div>
            <div style={{ fontFamily: F.serif, fontSize: 24 }}>›</div>
          </div>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
            <div onClick={() => setPickMode(true)} style={{ ...eyebrow, fontSize: 9, cursor: "pointer", textDecoration: "underline" }}>I know my door ›</div>
            <div onClick={() => { setDoor("SPIRITUAL"); next(); }} style={{ ...eyebrow, fontSize: 9, cursor: "pointer", color: C.mute }}>no door · a bit of each ›</div>
          </div>
          <div style={{ ...eyebrow, textAlign: "center", fontSize: 8, color: C.mute }}>eight doors, one house. walk in, look around, stay where it lands.</div></>); })()}
        {step === 4 && (<><Host>Meet your voice. <b style={{ fontWeight: 600 }}>{ic.name}</b> — {BIO[ic.wing]}. {ic.short} is in your ear for every {label(door)} lesson — says the word, you say it back, then reads you the story. It's a licensed voice, used with their permission, and it only ever reads words a Keeper has checked — it never improvises.</Host>
          <Face ic={ic} w="100%" h={260} radius={22} big />
          <div style={{ ...body, fontSize: 13, color: C.mute }}>The path is long on purpose: <b style={{ color: C.ink, fontWeight: 600 }}>five camps this year</b> — first steps, the stories, the practices, the text, the depths — and the deep texts for years after. {ic.short}'s voice, every session — the faith they actually grew up in.</div></>)}
        {step === 5 && (<><Host>How well do you know {label(door)}?</Host><div style={{ display: "grid", gap: 8 }}>{KNOW(door).map((k) => <Opt key={k} on={know === k} onClick={() => setKnow(k)}>{k}</Opt>)}</div></>)}
        {step === 9 && (<><Host>You know some already. Where do you want to start?</Host><div style={{ display: "grid", gap: 10 }}>
          <div onClick={() => setStart("find")} style={{ border: `2px solid ${start === "find" ? C.ink : C.line}`, background: start === "find" ? C.gold : "#fff", borderRadius: 18, padding: "16px 18px", cursor: "pointer", position: "relative" }}><div style={{ ...eyebrow, fontSize: 8, position: "absolute", top: -9, right: 14, background: C.ink, color: C.gold, borderRadius: 999, padding: "4px 10px" }}>recommended</div><div style={{ fontFamily: F.serif, fontWeight: 800, fontSize: 18 }}>find where I am</div><div style={{ ...body, fontSize: 13, marginTop: 4 }}>eight quick questions, two minutes. we start you where you actually are.</div></div>
          <div onClick={() => setStart("top")} style={{ border: `2px solid ${start === "top" ? C.ink : C.line}`, background: start === "top" ? "#FFFBE0" : "#fff", borderRadius: 18, padding: "16px 18px", cursor: "pointer" }}><div style={{ fontFamily: F.serif, fontWeight: 800, fontSize: 18 }}>start from the top</div><div style={{ ...body, fontSize: 13, marginTop: 4 }}>lesson one. the easiest one. also the best one.</div></div>
        </div><div style={{ ...body, fontSize: 12, color: C.mute }}>either way, day one is day one. days are earned; position isn't.</div></>)}
        {step === 6 && (<><Host>Here's what a lesson a day gets you.</Host><div style={{ display: "grid", gap: 14, padding: "4px 2px" }}>
          {[["A calmer mind", "One breath on day one. It grows slowly, and the path never guilts you."], [`Actually understand ${label(door)}`, `The words, the stories, the practices — in plain English, read by ${ic.short}.`], ["You're not alone", "Live counts on every door. When your voice reads live, your phone chimes once. Thousands of people, eight doors, one house."]].map(([a, b]) => <div key={a}><div style={{ fontFamily: F.serif, fontSize: 18 }}>{a}</div><div style={{ ...body, fontSize: 13, color: C.mute }}>{b}</div></div>)}</div></>)}
        {step === 7 && (<><Host>How much time do you have? Honestly.</Host><div style={{ display: "grid", gap: 8 }}>{[["3 min", "the sit", 21], ["5 min", "the sit + a page", 35], ["10 min", "the full session", 70]].map(([t, l, m], i) => <Opt key={t} on={time === i} onClick={() => setTime(i)} sub={l}>{t} a day</Opt>)}</div><div style={{ ...body, fontFamily: F.serif, fontSize: 16, color: "#6b6448" }}>That's <b style={{ color: C.amber, fontWeight: 600 }}>{[21, 35, 70][time]} minutes</b> with your own mind in the first week. More than most people get in a year.</div></>)}
        {step === 8 && (<div style={{ textAlign: "center", display: "flex", flexDirection: "column", alignItems: "center", gap: 18 }}><Guy pose="path" h={180} /><div style={{ ...h1, fontSize: 24, maxWidth: 280 }}>It's hard to stay with anything.<br /><em style={{ fontWeight: 300 }}>So infinite hill gives you one moment a day, and a lot of company.</em></div><div style={eyebrow}>did you know · every tradition on earth arrived at the golden rule on its own</div></div>)}
      </div>
      <div>
        {step === 1 && <Btn onClick={next} disabled={!heard}>Continue</Btn>}
        {step === 2 && <Btn onClick={next}>{why.length ? "Continue" : "Skip"}</Btn>}
        {step === 3 && <Btn onClick={next} disabled={!door}>{door ? (door === "SPIRITUAL" ? "Start my path" : `Open ${label(door)}`) : "Pick a door"}</Btn>}
        {step === 11 && <Btn onClick={next} disabled={!moment}>Continue</Btn>}
        {step === 12 && <Btn onClick={() => { setDoor(suggested); next(); }}>Try {label(suggested)} tonight</Btn>}
        {step === 4 && <Btn onClick={next}>Let's go</Btn>}
        {step === 5 && <Btn onClick={next} disabled={!know}>Continue</Btn>}
        {step === 9 && <Btn onClick={next} disabled={!start}>Continue</Btn>}
        {step === 6 && <Btn onClick={next}>Continue</Btn>}
        {step === 7 && <Btn onClick={next}>Start Day One</Btn>}
      </div>
    </div>
  );
}

// ─── Session player: renders any scripted session from CAMP1_HIN (falls back to DAY1 for other paths) ──

// ─── Lesson · the game before the read (v117) ────────────────────────────
// Duolingo's rhythm, our content. one tap, one verdict, next — every ten seconds. a combo that only rewards. the sun reacts.
// the exercises tell a story (Day One: a yoga class ends) instead of listing words. no hearts: a miss shows the answer, and the
// things you missed come back at the end. then the voice reads — that's the reward.
