LATER.SPIRITUAL["Camp 2"] = LATER.SPIRITUAL["Camp 2"].map((t, i) => i % 5 === 4 ? ["Marcus in bed, not wanting to get up (source: Meditations)", "Epictetus loses his leg (source: the Discourses)", "Zeno in the shipwreck (source: Diogenes Laërtius)", "Cato's last night (source: Plutarch)", "Seneca and the shortness of life (source: Seneca)"][Math.floor(i / 5) % 5] : t);
LATER.SPIRITUAL["Camp 3"] = LATER.SPIRITUAL["Camp 3"].map((t, i) => i % 4 === 3 ? ["the evening review — Seneca's three questions", "the dichotomy of control, applied", "the view from above", "memento mori as a daily practice"][Math.floor(i / 4) % 4] : t);
LATER.SPIRITUAL["Camp 4"] = LATER.SPIRITUAL["Camp 4"].map((t, i) => i >= 55 ? "Meditations, with Rumi — Marcus as the companion text" : t);
const camp1 = (wing) => wing === "HINDUISM" ? CAMP1_HIN : (CAMP1_ALL[wing] || CAMP1_ALL.SPIRITUAL);
// any lesson 1..331 → {title, word, carry, hook, segments?}
const lessonInfo = (wing, lesson) => {
  const p = pos(lesson);
  if (p.camp === "Camp 1") { const d = camp1(wing).find((x) => x.day === p.lesson); return d ? { ...d, camp: p } : null; }
  const titles = (LATER[wing] || LATER.SPIRITUAL)[p.camp] || []; const title = titles[p.lesson - 1] || p.name.toLowerCase();
  const kth = titles.slice(0, p.lesson).filter((t) => t === title).length; const total = titles.filter((t) => t === title).length;
  const shortT = title.length > 30 ? title.slice(0, 28).replace(/\s\S*$/, "") + "…" : title;
  const word = shortT.split(/[,;:]/)[0].split(" ").slice(0, 3).join(" ");
  const carry = `${p.name.toLowerCase()}: ${title}`;
  return { day: lesson, title: total > 1 ? `${shortT} · ${kth} of ${total}` : shortT, word, carry, hook: `${p.camp} — ${p.name.toLowerCase()}. this week: ${title}.`, camp: p, later: true,
    segments: [
      { type: "the bell", duration: null, voice: "", screen: [`DAY ${lesson}.`] },
      { type: "the hook", duration: "30 sec", voice: `${p.name}. Lesson ${p.lesson} of ${p.of}. This week: ${title}.`, screen: [`${p.name.toUpperCase()}`, `${title.toUpperCase()}`] },
      { type: "the teach", duration: "1 min", voice: `Camp one gave you the words. This camp gives you ${p.name.toLowerCase()} — today, ${title}. The Keeper's script for this session is being written; the shape is the same: a story, one idea, and something to try before tomorrow.`, screen: [`${title.toUpperCase()}`, "then: `ONE IDEA. ONE THING TO TRY.`"] },
      { type: "the practice", duration: "1 min", voice: "One minute. Breathe. Hold today's idea, and let the rest go.", screen: ["sky only, halo pulsing."] },
      { type: "the carry", duration: "15 sec", voice: `Your line to carry: ${carry}. Day ${lesson}. You showed up.`, screen: [carry.toUpperCase()] },
      { type: "the close", duration: null, voice: "", screen: [] }] };
};
// a different lesson every day: the exercise mix rotates, distractors come from the door's own other days
const dailyLesson = (wing, lesson) => {
  const info = lessonInfo(wing, lesson) || {}; const days = camp1(wing); const p = pos(lesson);
  const me = days.find((x) => x.day === p.lesson) || info;
  const others = days.filter((x) => x.word !== me.word);
  const pick = (k) => others[(lesson * 7 + k * 3) % Math.max(1, others.length)] || { word: "peace", carry: "be here" };
  const prev = days.filter((x) => x.day < p.lesson).slice(-2);
  const shuf = (arr, seed) => arr.map((v, i) => [Math.sin(seed * (i + 1)) , v]).sort((x, y) => x[0] - y[0]).map((x) => x[1]);
  const listen = { type: "listen", scene: me.hook ? me.hook.split(/[;—]/)[0] + "." : "you'll hear it first.", prompt: "which word is it?", speak: me.word, options: shuf([me.word, pick(1).word, pick(2).word], lesson), answer: null, answerText: me.word };
  const speak = { type: "speak", scene: "now you.", prompt: `say it back to ${icon(wing).short}.`, say: me.word, hint: "slowly. like you mean it." };
  const cw = (me.carry || "").split(" "); const tail = cw.slice(-2).join(" "); const head = cw.slice(0, -2).join(" ");
  const blank = { type: "blank", scene: "the line you'll carry today.", prompt: "finish the line.", before: head, after: "", options: shuf([tail, pick(3).carry.split(" ").slice(-2).join(" "), pick(4).carry.split(" ").slice(-2).join(" ")], lesson + 1), answer: null, answerText: tail };
  const pairs = [[me.word, me.carry], ...prev.map((d) => [d.word, d.carry])].slice(0, 3);
  const match = pairs.length >= 2 ? { type: "match", scene: "the words you've got so far.", prompt: "tap the pairs.", pairs } : null;
  const meaning = { type: "listen", scene: "what's underneath it?", prompt: `${me.word} — what's it actually saying?`, speak: me.word, options: shuf([me.carry, pick(5).carry, pick(6).carry], lesson + 2), answer: null, answerText: me.carry };
  const mixes = [[listen, speak, blank, match], [match, meaning, speak, blank], [listen, blank, match, speak], [meaning, listen, speak, blank]];
  const steps = mixes[lesson % mixes.length].filter(Boolean);
  return { word: me.word, script: null, say: me.word, open: p.camp === "Camp 1" ? `${me.hook ? me.hook.split(/[;—]/)[0] : "today's word is " + me.word}.\n${steps.length} quick ones, then ${icon(wing).short} reads.` : `${p.name.toLowerCase()} · lesson ${p.lesson}.\n${steps.length} quick ones, then the read.`, steps };
};

const genericLesson = (d1) => ({
  word: d1.word, script: null, say: d1.word,
  open: `today's word is ${d1.word}. three quick ones, then the read.`,
  steps: [
    { type: "listen", scene: "you'll hear it first.", prompt: "which word is it?", speak: d1.word, options: [d1.word, "peace", "thank you"].sort(() => Math.random() - 0.5), answer: null, answerText: d1.word },
    { type: "speak", scene: "now you.", prompt: "say it back.", say: d1.word, hint: "slowly. like you mean it." },
    { type: "blank", scene: "and the line you'll carry today.", prompt: "finish the line.", before: d1.carry.split(" ").slice(0, -2).join(" "), after: "", options: [d1.carry.split(" ").slice(-2).join(" "), "for now", "and then"], answer: 0 }
  ]
});
const NICE = ["nice.", "that's it.", "yep.", "you've got it.", "easy.", "look at you."];
const MISS = ["not quite —", "close —", "nope, but —", "almost —"];

function Lesson({ wing, lesson = 1, voiceOn, onDone }) {
  const ic = icon(wing);
  const L = useMemo(() => {
    if (wing === "HINDUISM" && lesson === 1) return LESSONS.HINDUISM;
    return dailyLesson(wing, lesson);
  }, [wing, lesson]);
  const [phase, setPhase] = useState("open"); // open · play · fix · done
  const [queue, setQueue] = useState(() => L.steps.map((_, k) => k));
  const [qi, setQi] = useState(0);
  const [state, setState] = useState(null);
  const [combo, setCombo] = useState(0); const [best, setBest] = useState(0);
  const [right, setRight] = useState(0); const [missed, setMissed] = useState([]);
  const [flash, setFlash] = useState(null);
  const [mood, setMood] = useState("calm");
  const [explain, setExplain] = useState(false); const [t0] = useState(() => Date.now());
  const total = L.steps.length;
  const stepIdx = queue[qi]; const step = stepIdx !== undefined ? L.steps[stepIdx] : null;
  const fixing = phase === "fix";
  const progress = fixing ? 1 : Math.min(1, qi / total);

  useEffect(() => { if (!step || phase === "open") return; if (step.type === "listen") setTimeout(() => speak(step.speak, voiceOn), 350); else if (step.scene) speak(step.scene, voiceOn); }, [qi, phase]);

  const advance = () => {
    setState(null); setMood("calm");
    if (qi + 1 < queue.length) { setQi(qi + 1); return; }
    if (phase === "play" && missed.length) { setPhase("fixintro"); return; }
    setPhase("done");
  };
  const verdict = (ok, answer) => {
    if (state) return;
    setState({ ok, answer });
    if (ok) {
      const c = combo + 1; setCombo(c); setBest((b) => Math.max(b, c)); setMood("happy");
      if (!fixing) setRight((r) => r + 1);
      if (c === 3 || c === 5 || c === 7) { setFlash(`combo x${c}`); setTimeout(() => setFlash(null), 800); }
      setTimeout(advance, 520);
    } else {
      setCombo(0); setMood("oops");
      if (!fixing && !missed.includes(stepIdx)) setMissed((m) => [...m, stepIdx]);
      setTimeout(advance, 1250);
    }
  };
  const startFix = () => { setQueue(missed); setQi(0); setPhase("fix"); setCombo(0); };

  // ── screens ──
  if (phase === "open") return (
    <div style={{ position: "absolute", inset: 0, background: C.cream, color: C.ink, zIndex: 100, display: "flex", flexDirection: "column", padding: "16px 20px 22px" }}>
      <div onClick={() => onDone(true)} style={{ ...eyebrow, cursor: "pointer", alignSelf: "flex-start" }}>✕</div>
      <div style={{ flex: 1, display: "flex", flexDirection: "column", justifyContent: "center", gap: 18 }}>
        <div style={{ display: "flex", gap: 14, alignItems: "flex-start" }}><Face ic={ic} w={64} h={64} radius={32} caption={false} /><Bubble>{L.open.split("\n").map((l, k) => <div key={k}>{l}</div>)}</Bubble></div>
        <div style={eyebrow}>{label(wing)} · lesson {lesson} · {L.word}</div>
        <div style={{ ...h1, fontSize: 30 }}>{total} quick ones with {ic.short}.<br /><em style={{ fontWeight: 300 }}>then the story.</em></div>
        <div style={{ ...body, color: C.mute }}>no hearts. no timer. a wrong tap just shows you the answer and moves on.</div>
      </div>
      <Btn onClick={() => setPhase("play")}>let's go</Btn>
    </div>
  );
  if (phase === "fixintro") return (
    <div style={{ position: "absolute", inset: 0, background: C.cream, color: C.ink, zIndex: 100, display: "flex", flexDirection: "column", padding: "16px 20px 22px" }}>
      <div style={{ flex: 1, display: "flex", flexDirection: "column", justifyContent: "center", gap: 18 }}>
        <div style={{ display: "flex", gap: 14, alignItems: "flex-start" }}><Sun size={64} mood="calm" /><Bubble>let's fix the {missed.length === 1 ? "one" : missed.length} you missed. no hearts, remember — you just get to see it again.</Bubble></div>
        <div style={{ ...h1, fontSize: 30 }}>almost there.</div>
      </div>
      <Btn onClick={startFix}>fix {missed.length === 1 ? "it" : "them"}</Btn>
    </div>
  );
  if (phase === "done") return (
    <div style={{ position: "absolute", inset: 0, background: C.ink, color: "#fff", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", textAlign: "center", padding: 24, zIndex: 100 }}>
      <Guy pose="one" h={170} />
      <div style={{ ...h1, fontSize: 32, color: C.gold, marginTop: 22 }}>you earned it.</div>
      <div style={{ ...body, color: "#ffffffd9", marginTop: 10 }}>{right} of {total} first try{best >= 3 ? ` · best combo x${best}` : ""}.{missed.length ? " the ones you missed, you fixed." : " clean run."}</div>
      <div style={{ ...body, color: "#ffffffd9", marginTop: 18, fontSize: 15 }}>now {ic.short} reads you {lesson === 1 ? "day one" : "the lesson"}.</div>
      <div style={{ marginTop: 22 }}><Btn kind="gold" onClick={() => onDone(false, { right, total, word: L.word, minutes: Math.max(1, Math.round((Date.now() - t0) / 60000)) + 2 })}>play the read →</Btn></div>
    </div>
  );

  // ── play / fix ──
  const Feedback = () => state ? <div style={{ position: "absolute", left: 0, right: 0, bottom: 0, padding: "16px 20px 22px", background: state.ok ? C.gold : "#F2F2EC", color: C.ink, fontFamily: F.sans, fontWeight: 700, fontSize: 14, zIndex: 3, display: "flex", gap: 12, alignItems: "center", animation: "drop .2s ease-out" }}>{state.ok ? <Face ic={ic} w={34} h={34} radius={17} caption={false} /> : <Sun size={34} mood="oops" />}<div style={{ flex: 1 }}>{state.ok ? NICE[(qi + stepIdx) % NICE.length] : <>{MISS[qi % MISS.length]} it's <b>“{state.answer}”</b>. moving on.</>}</div><div onClick={(e) => { e.stopPropagation(); setExplain(true); }} style={{ ...eyebrow, fontSize: 7.5, border: `1.5px solid ${C.ink}`, borderRadius: 999, padding: "6px 10px", cursor: "pointer", whiteSpace: "nowrap" }}>explain</div></div> : null;
  const Opt = ({ label: l, onClick, picked, correct }) => <div onClick={onClick} style={{ background: correct ? C.gold : picked ? "#F2F2EC" : "#fff", border: `2px solid ${C.ink}`, borderRadius: 16, padding: "14px 16px", fontFamily: F.sans, fontWeight: 600, fontSize: 15, cursor: "pointer", transition: "background .15s" }}>{l}</div>;
  const inner = (() => {
    if (step.type === "match") return <MatchStep key={`m${qi}${phase}`} step={step} onDone={(ok) => verdict(ok, step.pairs.map((p) => p.join(" = ")).join(" · "))} />;
    if (step.type === "listen" || step.type === "script") {
      const ans = step.answer !== null && step.answer !== undefined ? step.options[step.answer] : step.answerText;
      return <div style={{ display: "grid", gap: 10 }}>
        {step.type === "listen" && <div onClick={() => speak(step.speak, voiceOn)} style={{ justifySelf: "center", width: 88, height: 88, borderRadius: 44, background: C.gold, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 30, cursor: "pointer", marginBottom: 10 }}>🔊</div>}
        {step.type === "script" && <div style={{ fontFamily: F.serif, fontSize: 64, textAlign: "center", margin: "6px 0 14px" }}>{step.script}</div>}
        {step.options.map((o) => <Opt key={o} label={o} picked={state && state.picked === o} correct={state && o === ans} onClick={() => { if (state) return; const ok = o === ans; setState({ ok, answer: ans, picked: o }); verdict(ok, ans); }} />)}
      </div>;
    }
    if (step.type === "speak") return <SpeakStep key={`s${qi}${phase}`} step={step} onDone={() => verdict(true, "")} />;
    if (step.type === "order") return <OrderStep key={`o${qi}${phase}`} step={step} onDone={(ok) => verdict(ok, step.items.join(" → "))} />;
    if (step.type === "blank") return <div>
      <div style={{ fontFamily: F.serif, fontWeight: 800, fontSize: 24, lineHeight: 1.25, marginBottom: 18 }}>{step.before} <span style={{ borderBottom: `3px solid ${C.ink}`, padding: "0 30px" }}>{state ? state.picked : " "}</span> {step.after}</div>
      <div style={{ display: "grid", gap: 10 }}>{step.options.map((o) => { const ans = step.answer !== null && step.answer !== undefined ? step.options[step.answer] : step.answerText; return <Opt key={o} label={o} picked={state && state.picked === o} correct={state && o === ans} onClick={() => { if (state) return; const ok = o === ans; setState({ ok, answer: ans, picked: o }); verdict(ok, ans); }} />; })}</div>
    </div>;
    return null;
  })();
  const barLabel = fixing ? "fixing" : combo >= 2 ? `combo x${combo}` : qi === total - 1 ? "almost there" : null;
  return (
    <div style={{ position: "absolute", inset: 0, background: C.cream, color: C.ink, zIndex: 100, display: "flex", flexDirection: "column" }}>
      <div style={{ padding: "16px 18px 6px", display: "flex", alignItems: "center", gap: 12, position: "relative" }}>
        <div onClick={() => onDone(true)} style={{ ...eyebrow, cursor: "pointer" }}>✕</div>
        <div style={{ flex: 1, position: "relative" }}>
          {barLabel && <div style={{ position: "absolute", left: 0, right: 0, top: -14, textAlign: "center", ...eyebrow, fontSize: 9, color: combo >= 3 ? "#8a7a00" : C.mute }}>{barLabel}</div>}
          <div style={{ height: 10, background: "#e6e6e0", borderRadius: 999, overflow: "hidden", boxShadow: combo >= 3 ? `0 0 0 3px ${C.gold}88, 0 0 14px ${C.gold}` : "none", transition: "box-shadow .3s" }}><div style={{ width: `${progress * 100}%`, height: "100%", background: combo >= 3 ? "linear-gradient(90deg,#EEFF6A,#F5C400)" : C.gold, transition: "width .4s" }} /></div>
        </div>
        <Sun size={30} mood={mood} />
      </div>
      <div style={{ padding: "14px 20px 0", flex: 1, overflowY: "auto" }}>
        {fixing && <div style={{ ...eyebrow, color: "#8a7a00", marginBottom: 8 }}>↻ one more look</div>}
        <div style={{ display: "flex", gap: 10, alignItems: "center" }}><Face ic={ic} w={28} h={28} radius={14} caption={false} /><div style={{ ...body, fontSize: 14, color: C.mute }}>{step.scene}</div></div>
        <div style={{ ...h1, fontSize: 26, marginTop: 6, marginBottom: 18 }}>{step.prompt}</div>
        {inner}
        {step.hint && <div style={{ ...body, fontSize: 12, color: C.mute, marginTop: 14 }}>{step.hint}</div>}
      </div>
      {flash && <div style={{ position: "absolute", inset: 0, display: "flex", alignItems: "center", justifyContent: "center", pointerEvents: "none", zIndex: 5 }}><div style={{ fontFamily: F.mark, fontWeight: 800, fontSize: 54, color: C.gold, textShadow: `0 0 24px ${C.gold}, 0 4px 0 ${C.ink}`, transform: "rotate(-6deg)", animation: "pop .8s ease-out" }}>{flash}</div></div>}
      <Feedback />
      {explain && <ExplainSheet wing={wing} word={L.word} onClose={() => setExplain(false)} />}
    </div>
  );
}

// ─── Placement · "find where I am" (v117) ────────────────────────────────
// Duolingo's placement test is a lesson disguised as a test. eight quick questions from the camp, a gauge, a recommendation.
// days are still earned once — Day 1 is Day 1 — but your position on the path can start further up. nobody starts from zero twice.
const PLACEMENT = { ...PLACE_ALL,
  HINDUISM: [
    { q: "namaste. what's actually being said?", o: ["I bow to you", "thank you", "good night"], a: 0 },
    { q: "om is made of…", o: ["three sounds, then a silence", "one long sound", "seven notes"], a: 0 },
    { q: "dharma is closest to…", o: ["the thing that's yours to do", "fate", "a temple"], a: 0 },
    { q: "shanti is said three times because…", o: ["trouble comes from three directions", "it rhymes", "it's lucky"], a: 0 },
    { q: "Ganesha is the remover of…", o: ["obstacles", "doubt", "debt"], a: 0 },
    { q: "karma actually means…", o: ["action", "payback", "luck"], a: 0 },
    { q: "the beads on a mala. how many?", o: ["108", "100", "12"], a: 0 },
    { q: "you have the right to act — not to the…", o: ["fruit", "prize", "plan"], a: 0 }
  ]
};
const placeFromScore = (n, total) => { if (n <= 1) return { offset: 0, line: "start from the top. it's the best lesson anyway." }; if (n === total) return { offset: 21, line: "clean sweep. you're past camp one — we'll start you at the stories." }; const lesson = Math.min(20, 1 + Math.round((n / total) * 16)); if (lesson >= 21) return { offset: 21, line: "you're past camp one. we'll start you at the stories." }; return { offset: lesson - 1, line: `you already know ${n} of the ${total} we asked. we'll skip what you know.` }; };

function Placement({ wing, onDone }) {
  const items = useMemo(() => [...(PLACEMENT[wing] || [])].map((it) => ({ ...it, opts: [...it.o].map((t, k) => ({ t, ok: k === it.a })).sort(() => Math.random() - 0.5) })), [wing]);
  const [i, setI] = useState(0); const [picked, setPicked] = useState(null); const [right, setRight] = useState(0); const [combo, setCombo] = useState(0);
  const [mood, setMood] = useState("calm"); const [phase, setPhase] = useState("intro"); // intro · play · gauge · pick
  const [shown, setShown] = useState(0);
  const total = items.length;
  useEffect(() => { if (phase === "gauge") { let v = 0; const t = setInterval(() => { v += 1; setShown(v); if (v >= right) { clearInterval(t); setTimeout(() => setPhase("pick"), 900); } }, 160); if (right === 0) setTimeout(() => setPhase("pick"), 900); return () => clearInterval(t); } }, [phase]);
  const rec = placeFromScore(right, total);
  const p = pos(1 + rec.offset);
  const pick = (opt) => {
    if (picked) return; setPicked(opt.t);
    if (opt.ok) { setRight((r) => r + 1); setCombo((c) => c + 1); setMood("happy"); } else { setCombo(0); setMood("oops"); }
    setTimeout(() => { setPicked(null); setMood("calm"); if (i + 1 < total) setI(i + 1); else setPhase("gauge"); }, opt.ok ? 520 : 1100);
  };
  const shell = (kids, foot) => <div style={{ position: "absolute", inset: 0, background: C.cream, color: C.ink, zIndex: 110, display: "flex", flexDirection: "column", padding: "16px 20px 22px" }}>{kids}{foot}</div>;
  if (phase === "intro") return shell(
    <div style={{ flex: 1, display: "flex", flexDirection: "column", justifyContent: "center", gap: 18 }}>
      <div style={{ display: "flex", gap: 14, alignItems: "flex-start" }}><Sun size={64} /><Bubble>{total} quick ones about {label(wing)}. two minutes. nothing to lose — a miss just means we start you a lesson earlier.</Bubble></div>
      <div style={{ ...h1, fontSize: 30 }}>let's see where you are.</div>
      <div style={{ ...body, color: C.mute }}>day one is still day one. but nobody should learn namaste twice.</div>
    </div>,
    <div style={{ display: "grid", gap: 8 }}><Btn onClick={() => setPhase("play")}>find where I am</Btn><Btn kind="ghost" onClick={() => onDone(0)}>start from the top</Btn></div>
  );
  if (phase === "play") { const it = items[i]; return (
    <div style={{ position: "absolute", inset: 0, background: C.cream, color: C.ink, zIndex: 110, display: "flex", flexDirection: "column" }}>
      <div style={{ padding: "16px 18px 6px", display: "flex", alignItems: "center", gap: 12 }}>
        <div onClick={() => onDone(0)} style={{ ...eyebrow, cursor: "pointer" }}>✕</div>
        <div style={{ flex: 1, position: "relative" }}>
          {combo >= 2 && <div style={{ position: "absolute", left: 0, right: 0, top: -14, textAlign: "center", ...eyebrow, fontSize: 9, color: "#8a7a00" }}>combo x{combo}</div>}
          <div style={{ height: 10, background: "#e6e6e0", borderRadius: 999, overflow: "hidden", boxShadow: combo >= 3 ? `0 0 0 3px ${C.gold}88, 0 0 14px ${C.gold}` : "none" }}><div style={{ width: `${(i / total) * 100}%`, height: "100%", background: C.gold, transition: "width .4s" }} /></div>
        </div>
        <Sun size={30} mood={mood} />
      </div>
      <div style={{ padding: "18px 20px 0", flex: 1 }}>
        <div style={eyebrow}>{i + 1} of {total}</div>
        <div style={{ ...h1, fontSize: 26, marginTop: 8, marginBottom: 22 }}>{it.q}</div>
        <div style={{ display: "grid", gap: 10 }}>{it.opts.map((o) => <div key={o.t} onClick={() => pick(o)} style={{ background: picked && o.ok ? C.gold : picked === o.t ? "#F2F2EC" : "#fff", border: `2px solid ${C.ink}`, borderRadius: 16, padding: "14px 16px", fontFamily: F.sans, fontWeight: 600, fontSize: 15, cursor: "pointer", transition: "background .15s" }}>{o.t}</div>)}</div>
        {picked && <div style={{ ...body, marginTop: 16, fontWeight: 700 }}>{items[i].opts.find((o) => o.t === picked).ok ? NICE[i % NICE.length] : `it's “${items[i].o[items[i].a]}”. you'll get it on the path.`}</div>}
      </div>
    </div>
  ); }
  // gauge + pick
  const R = 92, cx = 120, cy = 118; const ang = (v) => Math.PI + (v / total) * Math.PI; const arc = (v) => { const a = ang(v); return `${cx + R * Math.cos(a)},${cy + R * Math.sin(a)}`; };
  const pathFor = (v) => v <= 0 ? "" : `M ${arc(0)} A ${R} ${R} 0 ${v / total > 0.5 ? 1 : 0} 1 ${arc(v)}`;
  return shell(
    <div style={{ flex: 1, display: "flex", flexDirection: "column", justifyContent: "center", alignItems: "center", textAlign: "center", gap: 10 }}>
      <div style={{ display: "flex", gap: 14, alignItems: "flex-start", alignSelf: "stretch", textAlign: "left" }}><Sun size={56} mood={phase === "pick" ? "happy" : "calm"} /><Bubble>{phase === "pick" ? rec.line : "adding it up…"}</Bubble></div>
      <svg width="240" height="140" viewBox="0 0 240 140" style={{ marginTop: 10 }}>
        <path d={`M ${arc(0)} A ${R} ${R} 0 0 1 ${arc(total)}`} fill="none" stroke="#e6e6e0" strokeWidth="14" strokeLinecap="round" />
        {shown > 0 && <path d={pathFor(shown)} fill="none" stroke={C.gold} strokeWidth="14" strokeLinecap="round" style={{ filter: `drop-shadow(0 0 8px ${C.gold})` }} />}
        <text x="120" y="112" textAnchor="middle" style={{ fontFamily: F.serif, fontWeight: 800, fontSize: 56, fill: C.ink, letterSpacing: "-0.04em" }}>{shown}</text>
        <text x="28" y="136" style={{ fontFamily: F.sans, fontWeight: 600, fontSize: 11, fill: C.mute }}>0</text>
        <text x="212" y="136" textAnchor="end" style={{ fontFamily: F.sans, fontWeight: 600, fontSize: 11, fill: C.mute }}>{total}</text>
      </svg>
      <div style={eyebrow}>of {total} · {label(wing)} · camp one</div>
      {phase === "pick" && <div style={{ display: "grid", gap: 10, alignSelf: "stretch", marginTop: 14, textAlign: "left" }}>
        <div onClick={() => onDone(rec.offset)} style={{ background: C.gold, border: `2px solid ${C.ink}`, borderRadius: 18, padding: "16px 18px", cursor: "pointer", position: "relative" }}>
          <div style={{ ...eyebrow, fontSize: 8, position: "absolute", top: -9, right: 14, background: C.ink, color: C.gold, borderRadius: 999, padding: "4px 10px" }}>recommended</div>
          <div style={{ fontFamily: F.serif, fontWeight: 800, fontSize: 18 }}>{rec.offset === 0 ? "start at lesson one" : `start at ${p.camp.toLowerCase()} · lesson ${p.lesson}`}</div>
          <div style={{ ...body, fontSize: 13, marginTop: 4 }}>{rec.offset === 0 ? `${camp1(wing)[0].title}. a few minutes.` : rec.offset >= 21 ? "the stories. Ganesha's race around the world." : `${(camp1(wing)[rec.offset] || {}).title || "lesson " + (rec.offset + 1)}. day one still counts as day one.`}</div>
        </div>
        {rec.offset > 0 && <div onClick={() => onDone(0)} style={{ background: "#fff", border: `2px solid ${C.ink}`, borderRadius: 18, padding: "16px 18px", cursor: "pointer" }}>
          <div style={{ fontFamily: F.serif, fontWeight: 800, fontSize: 18 }}>start from the top anyway</div>
          <div style={{ ...body, fontSize: 13, marginTop: 4 }}>lesson one, {camp1(wing)[0].word}. honestly a good call too.</div>
        </div>}
      </div>}
    </div>,
    null
  );
}

function MatchStep({ step, onDone }) {
  const left = step.pairs.map((p) => p[0]); const right = useMemo(() => [...step.pairs.map((p) => p[1])].sort(() => Math.random() - 0.5), []);
  const [sel, setSel] = useState(null); const [got, setGot] = useState({}); const [miss, setMiss] = useState(0);
  const tryPair = (l, r) => { const ok = step.pairs.find((p) => p[0] === l)[1] === r; if (ok) { const g = { ...got, [l]: r }; setGot(g); setSel(null); if (Object.keys(g).length === step.pairs.length) setTimeout(() => onDone(miss === 0), 300); } else { setMiss((m) => m + 1); setSel(null); } };
  const chip = (txt, active, done, onClick) => <div onClick={done ? undefined : onClick} style={{ background: done ? C.gold : active ? C.ink : "#fff", color: active ? "#fff" : C.ink, border: `2px solid ${C.ink}`, borderRadius: 16, padding: "14px 12px", fontFamily: F.sans, fontWeight: 700, fontSize: 14, textAlign: "center", opacity: done ? 0.7 : 1, cursor: "pointer" }}>{txt}</div>;
  return <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
    <div style={{ display: "grid", gap: 10 }}>{left.map((l) => chip(l, sel === l, !!got[l], () => setSel(l)))}</div>
    <div style={{ display: "grid", gap: 10 }}>{right.map((r) => chip(r, false, Object.values(got).includes(r), () => sel && tryPair(sel, r)))}</div>
  </div>;
}
function SpeakStep({ step, onDone }) {
  const [rec, setRec] = useState(false); const [heard, setHeard] = useState(null);
  const go = () => {
    setRec(true);
    const SR = typeof window !== "undefined" && (window.SpeechRecognition || window.webkitSpeechRecognition);
    let finished = false; const finish = (txt) => { if (finished) return; finished = true; setHeard(txt); setRec(false); setTimeout(onDone, 900); };
    if (SR) { try { const r = new SR(); r.lang = "en-US"; r.onresult = (e) => finish(e.results[0][0].transcript); r.onerror = () => finish("we heard you"); r.onend = () => finish("we heard you"); r.start(); } catch (e) {} }
    setTimeout(() => finish("we heard you"), 3000);
  };
  return <div style={{ textAlign: "center" }}>
    <div style={{ fontFamily: F.serif, fontWeight: 800, fontSize: 44, letterSpacing: "-0.02em" }}>{step.say}</div>
    <div onClick={rec ? undefined : go} style={{ margin: "26px auto 0", width: 96, height: 96, borderRadius: 48, background: rec ? C.ink : C.gold, color: rec ? C.gold : C.ink, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 34, cursor: "pointer", boxShadow: rec ? `0 0 0 14px ${C.gold}55` : "none", transition: "all .3s" }}>🎤</div>
    <div style={{ ...body, marginTop: 14, color: C.mute }}>{rec ? "listening…" : heard ? `“${heard}” — that's it.` : "tap and say it"}</div>
  </div>;
}
function OrderStep({ step, onDone }) {
  const [pool, setPool] = useState(() => [...step.items].sort(() => Math.random() - 0.5)); const [seq, setSeq] = useState([]);
  const pick = (x) => { const s2 = [...seq, x]; const p2 = pool.filter((y) => y !== x); setSeq(s2); setPool(p2); if (p2.length === 0) setTimeout(() => onDone(s2.every((v, k) => v === step.items[k])), 300); };
  return <div>
    <div style={{ display: "grid", gap: 8, minHeight: 60, marginBottom: 14 }}>{seq.map((x, k) => <div key={x} style={{ background: C.gold, borderRadius: 14, padding: "12px 14px", fontFamily: F.sans, fontWeight: 700, fontSize: 14 }}>{k + 1}. {x}</div>)}</div>
    <div style={{ display: "grid", gap: 8 }}>{pool.map((x) => <div key={x} onClick={() => pick(x)} style={{ background: "#fff", border: `2px solid ${C.ink}`, borderRadius: 14, padding: "12px 14px", fontFamily: F.sans, fontWeight: 600, fontSize: 14, cursor: "pointer" }}>{x}</div>)}</div>
  </div>;
}

const WELCOME = {"CHRISTIANITY": "I'm Denzel Washington. I'm a Christian, and I'm honored to be with you as you explore this faith. I'm proud of you for being here. We're going to do this together. Check the Together tab for community and events, use the Guide whenever you have a question, and let's begin. It's going to be a special ride.", "CATHOLIC": "I'm Mark Wahlberg. I'm a practicing Catholic, and I'm honored to be on this journey with you. I'm proud of you for showing up. We're going to do this together — one day at a time. The Together tab is where the community lives, the Guide is there for any question, and I'll be here every day. Let's go.", "JUDAISM": "I'm Natalie Portman. I'm Jewish, and I'm honored to walk this path with you. I'm proud of you for being here. We'll do it together. Look in the Together tab for community and events, ask the Guide anything you're wondering, and let's begin. It's going to be a special ride.", "ISLAM": "I'm Mahershala Ali. I'm a Muslim, and I'm honored to be beside you as you explore Islam. I'm proud of you for being here. We're going to do this together. The Together tab has community and events, the Guide is there whenever you have a question, and I'll be with you every day. Let's begin.", "HINDUISM": "I'm Priyanka Chopra. I'm a Hindu, and I'm honored to be on your journey as you explore this tradition. I'm proud of you for being here. We're going to do this together. Check the Together tab for community and events, use the Guide for any question, and let's start. It's going to be a special ride.", "BUDDHISM": "I'm Orlando Bloom. I'm a practicing Buddhist, and I'm honored to be on your journey to further explore Buddhism. I'm proud of you for being here, and we're going to do it together. Don't forget the Together tab for community events and activities, and use the Guide if you have any questions. It's going to be a special ride.", "SIKHISM": "I'm Diljit Dosanjh. I'm a Sikh, and I'm honored to walk with you as you explore this path. I'm proud of you for being here. We're going to do it together. The Together tab is where you'll find community and events, the Guide is there for your questions, and I'll be here every day. Let's begin.", "SPIRITUAL": "I'm Justin Bieber. I don't come at this from one religion — I come at it from needing somewhere to sit. If that's you, you're in the right place, and I'm honored to do this with you. I'm proud of you for showing up. Check the Together tab for community and events, use the Guide whenever you want, and let's begin. It's going to be a special ride."};

function parseDur(d) { if (!d) return 2500; const m = d.match(/(\d+)\s*min(?:\s*(\d+))?|(\d+)\s*sec/); if (!m) return 2500; if (m[3]) return parseInt(m[3]) * 1000; return parseInt(m[1]) * 60000 + (m[2] ? parseInt(m[2]) * 1000 : 0); }
// ─── the day, one flow (v144) ─────────────────────────────────────────────
// Sept 9, after Shaan's Duolingo screens. v143 asked the word six ways; the warm-up and the read were two flows testing the same thing.
// Now one flow, ~24 screens: story beats (tap-through, ≤45 words, at most 4 per segment) interleaved with exercises, each concept tested ONCE in the form that fits it:
//   guess the meaning (before the teach; any answer is fine) · put the ideas in order (the teach's own lines) · tap the pairs (words so far, or the word's parts on day one)
//   · which did you hear · the sit (sun breathes, ring, "I'm done") · say it back · tap what you hear (the carry line, word bank — Duolingo's "translate this sentence")
// Their mechanics, our objects: combo → "×N in a row" and the sun glows · Duo's "let's fix some mistakes" → the sun's "one more time" — only the ones you missed, no energy, no hearts
// · XP/gems/chests → none; the tally is a word, ideas, and a sit. "next" on every screen; voice never gates progress.
const splitBeats = (text, maxWords = 45, maxBeats = 4) => {
  if (!text) return [];
  const sents = text.split(/(?<=[.!?…])\s+(?=[A-Z0-9'"“‘(—-])/).map((s) => s.trim()).filter(Boolean);
  let out = []; let cur = "";
  for (const s of sents) { const w = (cur + " " + s).trim().split(/\s+/).length; if (cur && w > maxWords) { out.push(cur); cur = s; } else cur = (cur + " " + s).trim(); }
  if (cur) out.push(cur);
  while (out.length > maxBeats) { let bi = 0, bl = Infinity; for (let k = 0; k < out.length - 1; k++) { const l = out[k].length + out[k + 1].length; if (l < bl) { bl = l; bi = k; } } out.splice(bi, 2, out[bi] + " " + out[bi + 1]); }
  return out;
};
const screenLines = (arr) => { const out = []; (arr || []).forEach((s) => { const m = [...s.matchAll(/`([^`]+)`/g)].map((x) => x[1]); if (m.length) out.push(...m); else if (s && s.length < 40 && !/only|halo|pulsing|strand|clicks|returns/i.test(s)) out.push(s.toUpperCase()); }); return out.map((x) => x.replace(/\.$/, "")).filter((x) => x.length > 2 && !/^DAY /.test(x)); };
const shuffleSeed = (arr, seed) => arr.map((v, i) => [Math.sin(seed * 7.13 + i * 3.7), v]).sort((a, b) => a[0] - b[0]).map((x) => x[1]);
const strip = (s) => (s || "").replace(/[.!?,;:"“”'’]/g, "").toLowerCase().trim();

function buildDay({ wing, day, lesson, data, d1, segs, demoFast, mode = "adult" }) {
  const A = mode === "adult" && day === 1 ? (ADULT[wing] || null) : null; // v161: adult mechanics for Day 1 on every door; the kid drills stay behind mode="kid"
  const ic = icon(wing); const days = camp1(wing);
  const word = data ? data.word : d1.word; const carry = (data ? data.carry : d1.carry).replace(/[.!]$/, "");
  const others = days.filter((x) => x.word !== word && x.carry);
  const pick = (k) => others[(lesson * 5 + k * 3) % Math.max(1, others.length)] || { word: "peace", carry: "be here" };
  const prev = days.filter((x) => x.day < (data ? data.day : day)).slice(-2);
  const authored = day === 1 && LESSONS[wing];
  const steps = []; let id = 0; const push = (s) => steps.push({ ...s, id: id++ });
  const beats = (g, cap) => { const heads = screenLines(g.screen); const bs = splitBeats(g.voice, 45, cap); bs.forEach((b, k) => push({ type: "beat", seg: g.type, text: b, head: heads.length ? heads[Math.min(heads.length - 1, Math.floor((k * heads.length) / Math.max(1, bs.length)))] : null })); return heads; };
  segs.forEach((g) => {
    const type = g.type || "";
    if (type.startsWith("the bell")) { push({ type: "bell", text: `Day ${day}.` }); return; }
    if (type.startsWith("the close")) return;
    if (type.startsWith("a welcome") || type.startsWith("welcome") || type.startsWith("review")) { beats(g, 2); return; }
    if (type.startsWith("the hook")) {
      beats(g, 3);
      if (A) { push({ type: "bet", word: A.word, options: shuffleSeed(A.bet.options, lesson + 1), answer: A.bet.answer, reveal: A.bet.reveal }); return; }
      push({ type: "guess", prompt: `${word} — what do you think it means?`, options: shuffleSeed([carry, pick(1).carry.replace(/[.!]$/, ""), pick(2).carry.replace(/[.!]$/, "")], lesson + 1), answer: carry, graded: false });
      return;
    }
    if (type.startsWith("the teach")) {
      const heads = beats(g, 4);
      if (A) { push({ type: "myth", items: A.myth }); push({ type: "fork", ...A.fork }); return; }
      const ideas = heads.filter((h) => h.length <= 46 && !/^(THEN|AND)\b/.test(h)).slice(0, 4);
      if (ideas.length >= 3) push({ type: "order", prompt: `put ${ic.short}'s ideas back in order.`, items: ideas.map((h) => h.toLowerCase()) });
      if (authored) { const m = LESSONS[wing].steps.find((s) => s.type === "match"); if (m) push({ type: "match", prompt: "what's actually inside the word — tap the pairs.", pairs: m.pairs }); }
      else { const pairs = [[word, carry], ...prev.map((d) => [d.word, d.carry.replace(/[.!]$/, "")])].slice(0, 3); if (pairs.length >= 2) push({ type: "match", prompt: "the words you've got so far — tap the pairs.", pairs }); }
      push({ type: "listen", prompt: "which one did you hear?", speak: word, options: shuffleSeed([word, pick(3).word, pick(4).word], lesson + 2), answer: word });
      return;
    }
    if (type.startsWith("the practice")) {
      if (day <= 7) push({ type: "beat", seg: type, text: day <= 2 ? "Nobody's going to ask you to meditate. One breath, on purpose, with the bell. That's the whole practice today — and it counts." : "Three breaths with the bell. In as the sun grows, out as it shrinks. That's it. No eyes closed unless you want to.", head: null });
      else { const bs = splitBeats(g.voice.replace(/\s*The bell holds the time\.?\s*(Go\.)?\s*$/i, ""), 45, 2); bs.forEach((b) => push({ type: "beat", seg: type, text: b, head: null })); }
      // the sit ladder (Sept 9 law): days 1–2 one breath with the bell · days 3–7 three breaths · week 2 45s · week 3 60–90s · Camp 3+ the real thing. Nobody is asked to meditate on day one.
      const ladder = day <= 2 ? { mode: "breath", n: 1 } : day <= 7 ? { mode: "breath", n: 3 } : day <= 14 ? { mode: "sit", secs: 45 } : day <= 21 ? { mode: "sit", secs: 75 } : { mode: "sit", secs: 120 };
      if (ladder.mode === "breath") push({ type: "breath", n: ladder.n }); else push({ type: "sit", secs: demoFast ? Math.min(20, ladder.secs) : ladder.secs });
      return;
    }
    if (type.startsWith("the word")) { beats(g, 1); if (A) { if (A.original) push({ type: "original", ...A.original }); push({ type: "trapdoor", word: A.word, floors: A.trapdoor }); return; } push({ type: "speak", say: word, hint: `slowly. like you mean it. say it back to ${ic.short}.` }); return; }
    if (type.startsWith("the carry")) {
      const first = splitBeats(g.voice, 45, 1)[0]; if (first) push({ type: "beat", seg: type, text: first, head: null });
      if (A) return;
      const words = carry.split(/\s+/); const extra = shuffleSeed([...new Set([pick(5).carry, pick(6).carry].join(" ").split(/\s+/).map(strip).filter((w) => w && !words.map(strip).includes(w)))], lesson).slice(0, 3);
      push({ type: "taphear", prompt: "tap what you hear — your line for today.", speak: carry, words, bank: shuffleSeed([...words, ...extra], lesson + 9), answer: words.map(strip).join(" ") });
      return;
    }
    beats(g, 2);
  });
  push({ type: "tally" });
  return { steps, word, carry, ic };
}

function TapHear({ step, voiceOn, onDone }) {
  const [seq, setSeq] = useState([]); const [state, setState] = useState(null);
  useEffect(() => { const t = setTimeout(() => speak(step.speak, voiceOn), 300); return () => clearTimeout(t); }, []);
  const bank = step.bank.map((w, k) => ({ w, k })); const used = new Set(seq.map((x) => x.k));
  const check = () => { const ok = seq.map((x) => strip(x.w)).join(" ") === step.answer; setState(ok); };
  const chip = (x, on) => <div key={x.k} onClick={() => { if (state !== null) return; on ? setSeq(seq.filter((y) => y.k !== x.k)) : setSeq([...seq, x]); }} style={{ background: on ? C.gold : "#fff", color: C.ink, border: `2px solid ${on ? C.gold : "#ffffff"}`, borderRadius: 14, padding: "10px 14px", fontFamily: F.sans, fontWeight: 700, fontSize: 15, cursor: "pointer" }}>{x.w}</div>;
  return <div style={{ width: "100%", display: "grid", gap: 14 }}>
    <div style={{ display: "flex", gap: 12, alignItems: "flex-end" }}><div style={{ ...h1, color: "#fff", fontSize: 24, textAlign: "left", flex: 1 }}>{step.prompt}</div><Guy pose="music" h={84} /></div>
    <div onClick={() => speak(step.speak, true)} style={{ justifySelf: "start", display: "flex", alignItems: "center", gap: 10, background: "#ffffff14", border: "1px solid #ffffff33", borderRadius: 999, padding: "10px 16px", cursor: "pointer", color: "#fff", fontFamily: F.sans, fontWeight: 600, fontSize: 13 }}>🔊 hear it again</div>
    <div style={{ minHeight: 56, borderBottom: "1px solid #ffffff33", padding: "6px 0 12px", display: "flex", flexWrap: "wrap", gap: 8, alignItems: "flex-start" }}>{seq.length ? seq.map((x) => chip(x, true)) : <div style={{ ...body, color: "#ffffff66", fontStyle: "italic" }}>tap the words in order…</div>}</div>
    <div style={{ display: "flex", flexWrap: "wrap", gap: 8, justifyContent: "center" }}>{bank.filter((x) => !used.has(x.k)).map((x) => chip(x, false))}</div>
    {state === null ? <Btn kind="gold" disabled={seq.length < step.words.length} onClick={check}>check</Btn>
      : <div style={{ display: "grid", gap: 10 }}><div style={{ ...body, fontFamily: F.serif, fontSize: 16, color: state ? C.gold : "#ffffffcc", textAlign: "center" }}>{state ? "that's your line." : `close — it's "${step.speak}."`}</div><Btn kind="gold" onClick={() => onDone(state)}>next</Btn></div>}
  </div>;
}

function OptionStep({ step, voiceOn, onDone }) {
  const [picked, setPicked] = useState(null);
  useEffect(() => { if (step.speak) { const t = setTimeout(() => speak(step.speak, voiceOn), 300); return () => clearTimeout(t); } }, []);
  const ok = picked !== null && picked === step.answer; const guess = step.graded === false;
  return <div style={{ display: "grid", gap: 10, width: "100%" }}>
    <div style={{ ...h1, color: "#fff", fontSize: 24, textAlign: "left", marginBottom: 4 }}>{step.prompt}</div>
    {step.speak && <div onClick={() => speak(step.speak, true)} style={{ justifySelf: "center", width: 84, height: 84, borderRadius: 42, background: C.gold, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 30, cursor: "pointer", margin: "6px 0 10px" }}>🔊</div>}
    {step.options.map((o) => {
      const on = picked === o; const reveal = picked !== null && !guess; const right = reveal && o === step.answer;
      return <div key={o} onClick={() => picked === null && setPicked(o)} style={{ border: `1.5px solid ${on || right ? C.gold : "#ffffff44"}`, background: right ? C.gold : on ? "#fff" : "#ffffff10", color: right || on ? C.ink : "#fff", borderRadius: 16, padding: "16px 18px", fontFamily: F.sans, fontWeight: 600, fontSize: 15, textAlign: "left", cursor: picked === null ? "pointer" : "default", transition: "all .2s" }}>{o}</div>;
    })}
    {picked !== null && <div style={{ marginTop: 6, display: "grid", gap: 10 }}>
      <div style={{ ...body, color: guess ? "#ffffffcc" : ok ? C.gold : "#ffffffcc", fontFamily: F.serif, fontSize: 16, textAlign: "center" }}>{guess ? "good guess. she's about to tell you." : ok ? NICE[step.prompt.length % NICE.length] : `${MISS[step.prompt.length % MISS.length]} it's "${step.answer}."`}</div>
      <Btn kind="gold" onClick={() => onDone(guess ? null : ok)}>next</Btn>
    </div>}
  </div>;
}

function BreathStep({ n, onDone }) {
  const [k, setK] = useState(0); const [phase, setPhase] = useState("ready"); // ready · in · out · done
  useEffect(() => {
    if (phase === "ready" || phase === "done") return;
    const t = setTimeout(() => { if (phase === "in") setPhase("out"); else { if (k + 1 >= n) { bell(); setPhase("done"); } else { setK(k + 1); setPhase("in"); } } }, 4000);
    return () => clearTimeout(t);
  }, [phase, k]);
  useEffect(() => { if (phase === "done") { const t = setTimeout(onDone, 1200); return () => clearTimeout(t); } }, [phase]);
  const big = phase === "in";
  return <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 18, width: "100%" }}>
    <div style={{ width: 200, height: 200, display: "flex", alignItems: "center", justifyContent: "center" }}><div style={{ transition: "transform 4s ease-in-out", transform: big ? "scale(1.25)" : "scale(0.9)" }}><Sun size={100} mood="none" /></div></div>
    {phase === "ready" && <>
      <div style={{ ...h1, color: "#fff", fontSize: 26, textAlign: "center" }}>{n === 1 ? "one breath. that's the practice." : `${n} breaths with the sun.`}</div>
      <div style={{ ...body, color: "#ffffffaa", textAlign: "center" }}>in as it grows. out as it shrinks. eyes open is fine.</div>
      <div style={{ width: "100%" }}><Btn kind="gold" onClick={() => { bell(); setPhase("in"); }}>{n === 1 ? "take it" : "start"}</Btn></div>
    </>}
    {(phase === "in" || phase === "out") && <>
      <div style={{ ...h1, color: C.gold, fontSize: 30 }}>{phase === "in" ? "in…" : "out…"}</div>
      {n > 1 && <div style={{ ...eyebrow, color: "#ffffff99", fontSize: 9 }}>{k + 1} of {n}</div>}
    </>}
    {phase === "done" && <div style={{ ...h1, color: C.gold, fontSize: 26, textAlign: "center" }}>{n === 1 ? "that counts. that was the whole thing." : "that was a practice. you just did one."}</div>}
  </div>;
}
function SitStep({ secs, demoFast, onDone }) {
  const [phase, setPhase] = useState("ready"); const [left, setLeft] = useState(secs);
  const doneAt = demoFast ? 8 : 30; const iv = useRef(null);
  useEffect(() => { if (phase !== "sitting") return; bell(); iv.current = setInterval(() => setLeft((x) => { if (x <= 1) { clearInterval(iv.current); bell(); setPhase("done"); return 0; } return x - 1; }), 1000); return () => clearInterval(iv.current); }, [phase]);
  useEffect(() => { if (phase === "done") { const t = setTimeout(onDone, 1000); return () => clearTimeout(t); } }, [phase]);
  const pct = 1 - left / secs; const R = 78; const circ = 2 * Math.PI * R;
  return <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 18, width: "100%" }}>
    <div style={{ position: "relative", width: 200, height: 200, display: "flex", alignItems: "center", justifyContent: "center" }}>
      <svg width="200" height="200" style={{ position: "absolute", inset: 0, transform: "rotate(-90deg)" }}><circle cx="100" cy="100" r={R} stroke="#ffffff22" strokeWidth="4" fill="none" /><circle cx="100" cy="100" r={R} stroke={C.gold} strokeWidth="4" fill="none" strokeDasharray={circ} strokeDashoffset={circ * (1 - pct)} strokeLinecap="round" style={{ transition: "stroke-dashoffset 1s linear" }} /></svg>
      <div style={{ animation: phase === "sitting" ? "breathe 8s ease-in-out infinite" : "none" }}><Guy pose="meditate" h={phase === "sitting" ? 112 : 96} /></div>
    </div>
    {phase === "ready" && <>
      <div style={{ ...h1, color: "#fff", fontSize: 26, textAlign: "center" }}>{secs} seconds. the sun breathes with you.</div>
      <div style={{ ...body, color: "#ffffffaa", textAlign: "center" }}>in as it grows. out as it shrinks. that's the whole job.</div>
      <div style={{ width: "100%" }}><Btn kind="gold" onClick={() => setPhase("sitting")}>start the sit</Btn></div>
    </>}
    {phase === "sitting" && <>
      <div style={{ fontFamily: F.serif, fontSize: 40, color: C.gold, fontWeight: 800 }}>{left}</div>
      <div style={{ ...body, color: "#ffffffaa", fontFamily: F.serif, fontSize: 16 }}>the sun holds the time.</div>
      {secs - left >= doneAt && <div onClick={() => { clearInterval(iv.current); bell(); setPhase("done"); }} style={{ ...eyebrow, color: "#ffffff99", cursor: "pointer", fontSize: 10, padding: 8 }}>I'm done ›</div>}
    </>}
    {phase === "done" && <div style={{ ...h1, color: C.gold, fontSize: 28 }}>that was a sit. you just did one.</div>}
  </div>;
}


