        <Row a="Also walking" b={visitWing ? `${label(visitWing)} · day ${visitDay} · read by ${icon(visitWing).short}` : "Walk a second door alongside your own — a parent's, a partner's, one you're curious about"} onClick={() => setAdding(!adding)} right={visitWing ? (adding ? "close" : "change") : (adding ? "close" : "add")} />
